(function(){var path=location.pathname;if(path.indexOf("/dashboard")===0){var OPEN=["/dashboard/login","/dashboard/scouts-desk","/dashboard/news"];if(OPEN.indexOf(path.replace(/\/+$/,""))===-1){var id=null;try{id=localStorage.getItem("fpl_team_id")}catch{}if(!id){var next=path+location.search+location.hash;location.replace("/dashboard/login?next="+encodeURIComponent(next))}}}})();
